package pe.edu.upeu.entregable1.modelo;public class Cliente extends Persona {    private int codigo_cliente;    private String direccion;    public Cliente() {    }    public Cliente(int idPersona, String nombres, String apellidos, String dni, int telefono, int codigo_cliente, String direccion) {        super(idPersona, nombres, apellidos, dni, telefono);        this.codigo_cliente = codigo_cliente;        this.direccion = direccion;    }    public int getCodigo_cliente() {        return codigo_cliente;    }    public void setCodigo_cliente(int codigo_cliente) {        this.codigo_cliente = codigo_cliente;    }    public String getDireccion() {        return direccion;    }    public void setDireccion(String direccion) {        this.direccion = direccion;    }    @Override    public void mostrarInfo(Persona p) {        super.mostrarInfo(p);        System.out.println("\nID CLIENTE: " + p.getIdPersona()                + "\nNOMBRES: " + p.getNombres()                + "\nAPELLIDOS: " + p.getApellidos()                + "\nDNI: " + p.getDni()                + "\nTELEFONO: " + p.getTelefono());    }}